import test from 'node:test';import assert from 'node:assert/strict';import {bridgeHarness} from './audit-bridge-harness.mjs';import {validateExplicitAdminTarget} from '../plugins/qq-components/life-relay-message/admin-target.mjs';
const resolve=name=>name==='示例联系人'||name==='10002'?'private:10002':null;
test('explicit relay destinations stay binding for supported contact verbs',()=>{for(const text of ['去私聊示例联系人说声晚安','告诉示例联系人晚安','问问示例联系人吃饭了吗','传话给示例联系人：晚安','电一电示例联系人：晚安']){assert.equal(validateExplicitAdminTarget({messages:[{text}],targetKey:'private:10003',resolve}).ok,false,text);assert.equal(validateExplicitAdminTarget({messages:[{text}],targetKey:'private:10002',resolve}).ok,true,text);}});
test('a permitted owner relay automatically admits once but cannot change its original recipient',async t=>{const h=await bridgeHarness({config:{ownerQQ:10001,allow:{private:['10001','10002','10003'],groups:[]},socialV2:{adminDev:{enabled:true,preset:'qq-admin'},relayAliases:{示例联系人:'private:10002'}}}});let server;t.after(async()=>{server?.closeAllConnections?.();if(server?.listening)await new Promise(r=>server.close(r));await h.close();});h.setMode('reserved2');h.setPresets(['standard','qq-chat-v2','qq-admin']);const key='private:10001',st=h.getSocialV2State(key);h.appendSocialV2Message(key,'示例管理员','去私聊示例联系人说声晚安','去私聊示例联系人说声晚安',false,true,'synthetic-relay',[],'10001',[],undefined,false,{bodyComplete:true});const sid=await h.ensureSession(key);await h.deliverPrompt(key,'',{wakeReason:'private'});await h.queueDshEnvelope({payload:{type:'session/event',sessionId:sid,event:{type:'turn/start',data:{turn:1}}}});server=h.startConsoleServer();if(!server.listening)await new Promise(r=>server.once('listening',r));const send=async userId=>{const r=await fetch('http://127.0.0.1:'+server.address().port+'/api/send/private',{method:'POST',headers:{'content-type':'application/json','x-console-token':'fixture-console-token','x-agent-call':'1','x-agent-token':st.agentToken},body:JSON.stringify({userId,message:'晚安',token:st.agentToken})});return r.json();};const wrong=await send('10003');assert.equal(wrong.ok,false);assert.match(JSON.stringify(wrong),/CROSS_SESSION_TARGET_MISMATCH/);assert.equal(h.calls.http.filter(c=>c.url.endsWith('/send_private_msg')).length,0);assert.equal((await send('10002')).ok,true);assert.equal((await send('10002')).ok,false);const sends=h.calls.http.filter(c=>c.url.endsWith('/send_private_msg'));assert.equal(sends.length,1);assert.equal(String(sends[0].body.user_id),'10002');});
